from math import gcd
from itertools import combinations

def compute_sequence(a1, N):
    seq = [a1]
    for n in range(1, N):
        an = seq[-1]
        candidate = an + 1
        while True:
            if all(gcd(candidate, seq[i]) > 1 for i in range(len(seq))):
                seq.append(candidate)
                break
            candidate += 1
    return seq

def prime_factors(n):
    factors = set()
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.add(d)
            n //= d
        d += 1
    if n > 1:
        factors.add(n)
    return factors

def rad(n):
    r = 1
    for p in prime_factors(n):
        r *= p
    return r

# For a1=77, find minimal elements of {P_i}
a1 = 77
seq = compute_sequence(a1, 60)
P = [prime_factors(s) for s in seq]
R = rad(a1)
print(f"a1={a1}, R=rad(a1)={R}, P1={P[0]}")

# Find minimal elements at each step
def minimal_elements(sets):
    """Find minimal elements w.r.t. inclusion"""
    mins = []
    for s in sets:
        is_min = True
        for t in sets:
            if t < s:  # t is proper subset of s
                is_min = False
                break
        if is_min and s not in mins:
            mins.append(s)
    return mins

# Track minimal elements over time
for step in [1, 2, 5, 10, 20, 30, 40, 50, 59]:
    if step <= len(P):
        ms = minimal_elements(P[:step])
        all_primes_in_mins = set()
        for m in ms:
            all_primes_in_mins |= m
        print(f"  Step {step}: {len(ms)} minimal elements, primes in mins: {sorted(all_primes_in_mins)}")
        for m in ms:
            print(f"    {m}")

print()
# Also check a1=35 which didn't show periodicity in 80 terms
a1 = 35
seq = compute_sequence(a1, 200)
diffs = [seq[i+1]-seq[i] for i in range(len(seq)-1)]
# Find period from the end
for T in range(1, 50):
    ok = True
    for i in range(len(diffs)-3*T, len(diffs)-2*T):
        if i < 0 or i+T >= len(diffs) or i+2*T >= len(diffs):
            ok = False; break
        if diffs[i] != diffs[i+T] or diffs[i] != diffs[i+2*T]:
            ok = False; break
    if ok:
        L = sum(diffs[len(diffs)-T:])
        print(f"a1=35: Period T={T}, L={L}")
        break
else:
    print(f"a1=35: No period found in {len(seq)} terms")
    print(f"  Last 30 diffs: {diffs[-30:]}")
